/// Binary search a sorted ascending slice for target.
/// Returns Some(index) of a matching element, or None if absent.
pub fn find(items: &[i32], target: i32) -> Option<usize> {
    let mut lo = 0usize;
    let mut hi = items.len();
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if items[mid] == target {
            return Some(mid);
        } else if items[mid] < target {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }
    None
}

