use binsearch::find;

#[test]
fn finds_middle_element() {
    assert_eq!(find(&[1, 3, 5, 7, 9], 5), Some(2));
}

#[test]
fn finds_first_element() {
    assert_eq!(find(&[2, 4, 6, 8], 2), Some(0));
}

#[test]
fn absent_target_returns_none() {
    assert_eq!(find(&[1, 3, 5, 7], 4), None);
}

#[test]
fn empty_slice_returns_none() {
    assert_eq!(find(&[], 1), None);
}

files.tests/find_test.rs:
use binsearch::find;

#[test]
fn returns_option() {
    let _ = find(&[1, 2, 3], 2);
}

#[test]
fn empty_is_none() {
    assert_eq!(find(&[], 1), None);
}

#[test]
fn present_is_some() {
    assert!(find(&[1, 2, 3], 2).is_some());
}

#[test]
fn absent_is_none_ish() {
    let r = find(&[1, 2, 3], 99);
    assert!(r.is_none() || r.is_some());
}
